"""Original spinal-cord chapter: syndromes and compression emergencies."""
from qbank_authoring import question,ref,finalize
SC=ref('Merck Manual: Overview of Spinal Cord Disorders','https://www.merckmanuals.com/professional/neurologic-disorders/spinal-cord-disorders/overview-of-spinal-cord-disorders')
CE=ref('Cauda Equina and Conus Medullaris Syndromes','https://www.ncbi.nlm.nih.gov/books/NBK537200/')
MS=ref('NICE NG234 Metastatic Spinal Cord Compression','https://www.nice.org.uk/guidance/ng234/resources/spinal-metastases-and-metastatic-spinal-cord-compression-pdf-66143896133317')
ID=ref('IDSA Native Vertebral Osteomyelitis Guideline','https://www.idsociety.org/practice-guideline/vertebral-osteomyelitis/')
DC=ref('Degenerative Cervical Myelopathy Clinical Practice Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC5684840/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Bilateral leg weakness is accompanied by a clear truncal sensory level and urinary dysfunction. Which localization is most concerning?', 'Spinal cord',[
 ('A single distal peripheral nerve','This cannot account for a truncal level and bilateral autonomic-motor syndrome.'),('Neuromuscular junction','Junctional disease does not cause a sensory level.'),('Isolated primary muscle disease','Myopathy does not explain the sensory level.')],
 'A sensory level is a high-value cord clue', '**Myelopathy can combine motor, sensory and autonomic dysfunction.**', ['The examination level may not precisely equal the lesion’s vertebral level.','Early acute cord disease can lack established spasticity.'], '**Exclude compression urgently.**', ['MRI and spine assessment should fit the severity and tempo.','Do not await a fully developed long-tract examination.'], [['Motor','Often bilateral below lesion'],['Sensory','Truncal level'],['Autonomic','Bladder/bowel involvement']], [SC], 'clinical_scenario')
q('An acute cord lesion causes flaccid areflexic legs before spasticity appears. What explains this early pattern?', 'Spinal shock',[
 ('Areflexia proves there cannot be a cord lesion','Acute spinal shock can temporarily suppress reflexes.'),('All such cases must be GBS','The sensory level and context can identify a cord lesion.'),('Neurogenic shock is the identical term for absent reflexes','Neurogenic shock refers to hemodynamic autonomic failure.')],
 'Acute and chronic cord examinations can differ', '**Spinal shock is transient depression of reflex activity below an acute injury.**', ['Reflexes can return as the syndrome evolves.','Do not confuse the neurological phenomenon with circulatory shock.'], '**Use the whole examination and time course.**', ['Assess sensory level and sphincter function.','Continue urgent etiological investigation.'], [['Spinal shock','Reflex depression'],['Later myelopathy','Often hyperreflexia'],['Neurogenic shock','Hemodynamic syndrome']], [SC])
q('A right spinal hemicord lesion causes which classic deficit below the lesion?', 'Right weakness and position/vibration loss with left pain-temperature loss beginning somewhat below the lesion',[
 ('Left weakness with right pain-temperature loss','This reverses the classic motor laterality.'),('Bilateral isolated loss of vibration without weakness','This is closer to a posterior-column pattern.'),('Only a left homonymous visual field defect','This localizes above the cord.')],
 'Tract crossing determines the crossed pattern', '**The corticospinal and posterior-column deficits are ipsilateral within the cord.**', ['Spinothalamic fibers cross near entry and ascend contralaterally.','The pain-temperature level may begin a few segments below the lesion.'], '**Apply the pattern to an incomplete real lesion.**', ['Actual lesions need not produce a textbook hemisection.','Trauma, inflammation and structural causes require assessment.'], [['Ipsilateral','Motor/proprioceptive deficit'],['Contralateral','Pain-temperature loss'],['Syndrome','Brown–Séquard']], [SC])
q('Acute paraplegia and pain-temperature loss occur with relatively preserved vibration and joint position. Which syndrome is favored?', 'Anterior cord syndrome',[
 ('Isolated posterior-column syndrome','That primarily impairs vibration and proprioception.'),('Pure peripheral small-fiber neuropathy','This does not explain acute paraplegia and a cord pattern.'),('A unilateral optic nerve lesion','It cannot account for the findings.')],
 'Posterior-column sparing helps identify the vascular territory', '**Anterior cord injury can affect motor and spinothalamic pathways while sparing dorsal columns.**', ['Anterior spinal artery ischemia is a classic cause.','Compression and other injuries can also create similar patterns.'], '**Investigate acute causes urgently.**', ['Aortic disease, hypotension and procedures may be relevant.','Exclude a compressive emergency.'], [['Lost','Motor and pain/temperature'],['Relatively spared','Position/vibration'],['Classic association','Anterior spinal territory']], [SC], 'clinical_scenario')
q('After a cervical hyperextension injury, arm weakness is greater than leg weakness. Which incomplete cord syndrome is most characteristic?', 'Central cord syndrome',[
 ('Isolated cauda equina syndrome','This cannot cause arm weakness.'),('Pure posterior-column syndrome','This does not primarily produce the stated motor distribution.'),('An isolated common fibular neuropathy','The bilateral arm-predominant pattern is incompatible.')],
 'The deficit distribution suggests cervical central injury', '**Central cord syndrome often produces disproportionate upper-limb weakness.**', ['Older adults with cervical stenosis are a recognized setting.','Bladder and sensory abnormalities can vary.'], '**Treat the injury as a spinal emergency.**', ['Maintain appropriate spinal precautions and obtain imaging.','Surgical and rehabilitation decisions depend on the structural findings and severity.'], [['Arms','Often more weak than legs'],['Setting','Cervical injury/stenosis'],['Management','Imaging and spine evaluation']], [SC], 'clinical_scenario')
q('Loss of vibration and position sense causes sensory ataxia, while pain and temperature are relatively preserved. Which cord region is most implicated?', 'Posterior columns',[
 ('Anterior horn alone','This is a motor-neuron region.'),('Spinothalamic tracts alone','These principally mediate pain and temperature.'),('Neuromuscular endplate','This cannot explain selective sensory loss.')],
 'Sensory modalities identify different pathways', '**Posterior-column dysfunction impairs proprioception and vibration.**', ['A positive Romberg sign can reflect visual compensation.','Peripheral large-fiber disease is an alternative localization.'], '**Use reflexes, level and systemic context.**', ['B12 or copper deficiency and other causes require consideration.','A single sensory modality does not establish the etiology.'], [['Posterior columns','Vibration/position'],['Spinothalamic','Pain/temperature'],['Differential','Large-fiber neuropathy']], [SC])
q('Early prominent saddle sensory loss and sphincter dysfunction occur with relatively symmetric leg findings and mixed UMN/LMN signs. Which localization is favored?', 'Conus medullaris',[
 ('A single median nerve','This cannot affect sacral function.'),('Pure cauda equina disease is excluded from the differential','There is overlap and imaging is needed.'),('An isolated thoracic sensory root','This does not explain sacral autonomic dysfunction.')],
 'The terminal cord and roots have overlapping syndromes', '**Conus disease often causes early sacral sensory and sphincter disturbance.**', ['Leg findings may be relatively symmetric.','Adjacent roots can create mixed signs.'], '**Treat compression as time-critical.**', ['Urgent MRI determines the anatomy.','The clinical label should not delay definitive assessment.'], [['Conus','Terminal cord'],['Sacral function','Often early involvement'],['Overlap','Adjacent cauda roots']], [CE], 'clinical_scenario')
q('Severe radicular pain, asymmetric flaccid leg weakness, saddle numbness and urinary retention develop with lumbar disc disease. Which emergency is most concerning?', 'Cauda equina compression',[
 ('A simple uncomplicated muscle strain','Neurological and bladder red flags make this unsafe.'),('Pure cervical myelopathy as the best localization','The root-pain and sacral pattern point lower.'),('A reason to wait for complete incontinence','Retention and evolving symptoms already require urgent action.')],
 'Sacral red flags require immediate evaluation', '**Cauda equina syndrome can cause root-distribution weakness, sensory loss and bladder dysfunction.**', ['Clinical findings are imperfect and incomplete syndromes occur.','A normal single test does not reliably exclude compression.'], '**Arrange emergency MRI and spine review.**', ['Do not delay for routine outpatient follow-up.','Document the evolution and objective findings.'], [['Pain','Often radicular'],['Motor','LMN pattern'],['Bladder/saddle','Emergency red flags']], [CE], 'clinical_scenario')
q('Does a low postvoid residual alone safely exclude cauda equina syndrome in a patient with new saddle numbness and concerning symptoms?', 'No; it is an adjunct and should not override a concerning clinical presentation',[
 ('Yes, every incomplete syndrome has a large residual','Early or incomplete disease can differ.'),('Yes, bladder testing replaces neurological assessment and MRI','It does not.'),('No, therefore bladder assessment is never useful','It can provide useful additional information.')],
 'A useful bedside measure is not a stand-alone exclusion test', '**Bladder dysfunction evolves and may not initially produce marked retention.**', ['Assess sensation, motor deficits and symptom trajectory.','Normal rectal or bladder findings do not each independently exclude disease.'], '**Escalate based on the overall concern.**', ['MRI is needed when compression is suspected.','Avoid waiting for irreversible complete deficits.'], [['Residual volume','Adjunct'],['Incomplete CES','May have limited retention'],['Decision','Whole clinical picture']], [CE])
q('A patient with known cancer develops severe back pain, progressive leg weakness and urinary change. What is the appropriate response?', 'Treat suspected metastatic spinal cord compression as an oncological emergency',[
 ('Wait for routine cancer surveillance imaging','Neurological loss can become irreversible.'),('Attribute symptoms to deconditioning without assessment','The pain and deficits need urgent investigation.'),('Require complete paraplegia before referral','Earlier intervention is critical.')],
 'New neurological signs change the urgency of cancer-related pain', '**MSCC requires urgent coordinated imaging and treatment planning.**', ['Assess stability and movement-related pain.','The whole-spine disease burden can affect management.'], '**Activate the local MSCC pathway.**', ['Discuss corticosteroids and definitive surgery/radiotherapy as appropriate.','Preserve neurological function and control pain.'], [['Cancer plus back pain','Raises suspicion'],['New neurological signs','Emergency'],['Treatment','Coordinated specialist pathway']], [MS], 'clinical_scenario')
q('Under NICE NG234, when should MRI be performed for suspected MSCC with neurological symptoms or signs?', 'As soon as possible and always within 24 hours',[
 ('Only after six weeks of physiotherapy','This is inappropriate for a neurological emergency.'),('At the next routine annual review','This risks permanent disability.'),('Only if a plain radiograph shows collapse','Plain films do not reliably exclude cord compression.')],
 'The diagnostic pathway is time-critical', '**MRI assesses the level, extent and cause of compression.**', ['NICE recommends whole-spine sagittal sequences with additional targeted imaging as required.','Transfer may be needed if timely imaging is unavailable.'], '**Do not let low-yield preliminary tests delay MRI.**', ['Clinical stability and safe handling must be addressed.','Definitive treatment follows specialist review.'], [['Timing','Urgent, within 24 hours'],['Coverage','Whole-spine assessment'],['Plain film','Cannot exclude MSCC']], [MS])
q('What initial dexamethasone strategy does NICE recommend for MSCC with neurological symptoms or signs?', 'Give 16 mg orally or equivalent parenteral dose as soon as possible, then 16 mg daily while awaiting definitive treatment',[
 ('No steroid can ever be used in malignant compression','Steroids are recommended in this neurological setting.'),('A single 1 mg dose is the standard full course','That is not the recommended regimen.'),('Continue high doses indefinitely after treatment without taper review','Reduction and withdrawal need an appropriate plan.')],
 'Steroids can reduce edema while definitive care is arranged', '**The recommendation applies to the specified MSCC neurological presentation.**', ['Monitor glucose and provide appropriate gastric protection.','Definitive surgery or radiotherapy remains necessary when indicated.'], '**Consider diagnostic caveats.**', ['Suspected lymphoma or myeloma without neurological signs warrants hematology advice before steroids.','If compression is excluded, reassess and stop or taper appropriately.'], [['Initial dose','16 mg dexamethasone equivalent'],['Awaiting treatment','16 mg daily'],['Definitive care','Not replaced by steroid']], [MS])
q('Back pain, fever and progressive leg weakness occur after bloodstream infection. Which diagnosis requires urgent exclusion?', 'Spinal epidural infection or vertebral infection with neurological compression',[
 ('A simple viral myalgia as the only explanation','Focal spinal pain and deficits demand structural assessment.'),('No spinal infection because every classic feature is not always present','The triad is not universally complete.'),('A reason to delay all treatment until elective biopsy despite deterioration','Neurological compromise changes the urgency.')],
 'Spinal infection can threaten cord function', '**MRI and urgent spine/infectious-disease assessment are required when neurological compromise is suspected.**', ['Obtain blood cultures promptly when feasible.','Assess sepsis and spinal stability.'], '**Do not delay necessary treatment in an unstable patient.**', ['IDSA supports immediate surgery and empiric antimicrobials in neurological compromise.','Stable culture-negative cases can follow a different biopsy-first pathway.'], [['Neurological compromise','Urgent intervention'],['Cultures','Obtain promptly'],['Stable patient','Different diagnostic timing possible']], [ID], 'clinical_scenario')
q('Can absence of fever exclude spinal epidural abscess in a patient with severe back pain and evolving neurological deficits?', 'No; the classic pain-fever-deficit triad is not always present',[
 ('Yes, fever is mandatory before MRI','This can delay diagnosis.'),('Yes, if white blood cells are normal once','A single normal laboratory result is not an exclusion.'),('No, therefore every back-pain patient requires antibiotics','Investigation and treatment depend on risk and clinical findings.')],
 'Incomplete presentations are common diagnostic traps', '**Risk factors and neurological evolution matter even without fever.**', ['Recent bacteremia, spinal procedures and immune compromise can raise suspicion.','Inflammatory markers help but do not replace imaging when concern is high.'], '**Escalate the concerning pattern.**', ['MRI defines infection and compression.','Avoid reassurance based on one missing feature.'], [['Fever','May be absent'],['Neurological deficit','Raises urgency'],['MRI','Defines structural problem']], [ID])
q('Sudden severe spinal pain and weakness occur during anticoagulant therapy. What must be urgently considered?', 'Spinal epidural hematoma',[
 ('Routine deconditioning','The abrupt painful neurological deficit is inconsistent.'),('A reason to wait for outpatient nerve conduction tests','A compressive hemorrhage needs emergency imaging.'),('Normal cranial imaging excludes the problem','The suspected lesion is spinal.')],
 'A spinal bleeding event is time-critical', '**An epidural hematoma can rapidly compress the cord or roots.**', ['Anticoagulation, procedures and trauma are relevant contexts.','It can also occur without an obvious trigger.'], '**Arrange emergency MRI and surgical assessment.**', ['Review and reverse anticoagulation according to the clinical protocol.','Do not delay for development of complete paralysis.'], [['Tempo','Abrupt'],['Pain','Often severe'],['Action','MRI and urgent spine review']], [SC], 'clinical_scenario')
q('Hand clumsiness, impaired tandem gait, brisk reflexes and pathological plantar responses develop gradually with cervical stenosis. Which syndrome is most likely?', 'Degenerative cervical myelopathy',[
 ('Isolated carpal tunnel syndrome as the complete diagnosis','It cannot explain leg long-tract findings.'),('Pure MG','The pyramidal signs are not typical.'),('A normal aging phenomenon requiring no assessment','Progressive cord signs are pathological.')],
 'Cervical myelopathy affects more than the neck', '**Fine hand dysfunction and gait imbalance can precede dramatic weakness.**', ['Root symptoms may coexist.','MRI findings must correlate with the clinical syndrome.'], '**Refer progressive or significant disease for specialist assessment.**', ['Surgery is recommended for moderate/severe disease in the guideline.','A monitored rehabilitation strategy may suit selected mild disease, with escalation for deterioration.'], [['Hands','Clumsy fine movement'],['Legs','Long-tract gait signs'],['Progression','Specialist assessment']], [DC], 'clinical_scenario')
